namespace Game.Runtime{
// Separate air/combined storage identity; this does not enable the ground ARIA controller.
internal static class SourceAirCombinedMissionAdmission{
 internal static void RequireCompiledStorage(Game.Configs.SkirmishResolvedSetup setup){
  if(setup==null||setup.EnemyPolicy==null||System.String.IsNullOrEmpty(setup.MissionLogicalBindingFingerprint)||setup.SetupHash!=Game.Configs.SkirmishSetupCompiler.ComputeHash(setup,setup.Seed)||!Game.Configs.SkirmishGenericAirCombinedEnemyRollout.Supports(setup))throw new System.NotSupportedException("Exact original compiled air-combined storage setup required");
 }
}
internal static class SourceGroundEnemyPolicyAdmission{internal static void Require(Game.Configs.SkirmishResolvedSetup setup){if(Game.Configs.SkirmishGenericAirCombinedEnemyRollout.IncludesCatalog(setup?.CatalogId)){if(setup.EnemyPolicy!=null&&Game.Configs.SkirmishGenericAirCombinedEnemyRollout.Supports(setup))return;throw new System.NotSupportedException("Exact compiled generic air-combined policy setup required");}if(setup!=null&&setup.CatalogId=="S003"&&setup.DefinitionId=="skirmish.s003"&&setup.ObjectiveKind==Game.Skirmish.Contracts.SkirmishObjectiveKind.BaseAssault&&setup.ArmyProfileId==Game.Skirmish.Contracts.SkirmishArmyProfileId.AirMobile&&setup.EnemyPolicy==null&&!Game.Configs.SkirmishGenericAirCombinedEnemyRollout.IncludesCatalog(setup.CatalogId)&&Game.Runtime.SkirmishEnemyPlannerService.EnsureSession(null,default,setup))return;if(setup==null||setup.ObjectiveKind!=Game.Skirmish.Contracts.SkirmishObjectiveKind.BaseAssault||setup.ArmyProfileId!=Game.Skirmish.Contracts.SkirmishArmyProfileId.GroundManeuver||(setup.EnemyPolicy==null?setup.CatalogId!="S002":!Game.Configs.SkirmishGenericGroundEnemyRollout.Supports(setup)))throw new System.NotSupportedException("Current S002 null-policy or actual generic ground/air-combined BaseAssault policy required");}}}
